39	export async function loadDealers(): Promise<Dealer[]> {
40	  const base = await readJson("dealers.json", z.array(DealerSchema));
41	  // Backfill dealer phone + address from per-listing enrichment when the
42	  // canonical dealers.json still has placeholder values. Unit→dealer map
43	  // built from units.json so we know which enrichment entry belongs to whom.
44	  let enrichment: Record<string, { phone?: string; streetAddress?: string }> = {};
45	  let unitsRaw: Array<{ id: string; dealerId: string }> = [];
46	  try {
47	    enrichment = JSON.parse(
48	      await fs.readFile(path.join(DATA_DIR, "units-enrichment.json"), "utf8"),
49	    );
50	    unitsRaw = JSON.parse(await fs.readFile(path.join(DATA_DIR, "units.json"), "utf8"));
51	  } catch (err) {
52	    if ((err as NodeJS.ErrnoException)?.code !== "ENOENT") throw err;
53	  }
54	  const dealerEnrich = new Map<string, { phone?: string; streetAddress?: string }>();
55	  for (const u of unitsRaw) {
56	    const e = enrichment[u.id];
57	    if (!e) continue;
58	    if (!dealerEnrich.has(u.dealerId)) dealerEnrich.set(u.dealerId, e);
59	  }
60	  return base.map((d) => {
61	    const e = dealerEnrich.get(d.id);
62	    if (!e) return d;
63	    const phone = !d.phone && e.phone ? e.phone : d.phone;
64	    const address =
65	      (!d.address || d.address === "Address not yet captured") && e.streetAddress
66	        ? e.streetAddress
67	        : d.address;
68	    return { ...d, phone, address };
69	  });
70	}
