207	  const [unitsStat, incStat, dealersStat, snaps] = await Promise.all([
208	    fs.stat(path.join(DATA_DIR, "units.json")),
209	    fs.stat(path.join(DATA_DIR, "incentives.json")),
210	    fs.stat(path.join(DATA_DIR, "dealers.json")),
211	    listSnapshotFiles(),
212	  ]);
213	  const lastSnapshotAt = snaps.length
214	    ? (await fs.stat(path.join(DATA_DIR, "snapshots", snaps[snaps.length - 1]))).mtime.toISOString()
215	    : null;
216	  return {
217	    unitsUpdatedAt: unitsStat.mtime.toISOString(),
